package com.smartsociety.platform.complaint; import com.smartsociety.platform.auth.User; import com.smartsociety.platform.common.Enums.ComplaintStatus; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="complaint_status_history",indexes=@Index(name="idx_history_complaint",columnList="complaint_id,created_at")) public class ComplaintHistory {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="complaint_id") Complaint complaint; @Enumerated(EnumType.STRING) ComplaintStatus fromStatus; @Enumerated(EnumType.STRING) ComplaintStatus toStatus; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="actor_id") User actor; @Column(length=1000) String note; Instant createdAt=Instant.now(); public void setComplaint(Complaint x){complaint=x;} public void setFromStatus(ComplaintStatus x){fromStatus=x;} public void setToStatus(ComplaintStatus x){toStatus=x;} public void setActor(User x){actor=x;} public void setNote(String x){note=x;} public Long getId(){return id;} public ComplaintStatus getFromStatus(){return fromStatus;} public ComplaintStatus getToStatus(){return toStatus;} public User getActor(){return actor;} public String getNote(){return note;} public Instant getCreatedAt(){return createdAt;} }
